import{_ as o,c as r,o as l,j as t,at as n,a as e}from"./chunks/framework.BlwsHpGA.js";const g=JSON.parse('{"title":"김민영 — 프론트엔드","description":"","frontmatter":{"layout":"doc","sidebar":false,"title":"김민영 — 프론트엔드","description":"","tags":["Frontend","Design System","Data Visualization","Vue","Nuxt"],"outline":false,"footer":false,"prev":false,"next":false},"headers":[],"relativePath":"resume.md","filePath":"resume.md"}'),i={name:"resume.md"};function s(h,a,d,u,c,p){return l(),r("div",null,[...a[0]||(a[0]=[t("h1",{id:"김민영",tabindex:"-1"},[e("김민영 "),t("a",{class:"header-anchor",href:"#김민영","aria-label":'Permalink to "김민영"'},"​")],-1),t("div",{className:"kicker"},"Frontend Engineer(Developer)",-1),t("div",{class:"be-button text gray"},[t("i",{class:"icon left xi-mail-o"}),e(" noistommy@gmail.com ")],-1),t("div",{class:"be-button text gray"},[t("i",{class:"icon left xi-mobile"}),e(" 010-4456-9329 ")],-1),t("hr",null,null,-1),t("div",{className:"lead"},[e(" 10년차 프론트엔드 개발자 김민영입니다. "),t("p",null,"다양한 프로젝트 경험으로 프론트엔드의 전반적인 업무를 폭넓게 수행해 왔습니다. 빠르게 변화하는 프론트엔드 기술의 특성과 목적을 명확히 이해하고, 상황에 맞는 효율적인 개발 방식을 적용하는데 중점을 두고 있습니다."),t("p",null,"기획부터 배포까지 전체 프로세스를 직접 경험하며 프로젝트 흐름을 빠르게 파악하고 그 과정에서 다양한 협업 파트너들과 적극적으로 의사소통을 하며 쌓은 협업 경험을 통해 문제 해결 능력과 실무 역량을 높여왔습니다."),t("p",null,"효율적인 프론트엔드 구조 설계와 UI/UX를 업무의 중요한 부분으로 두고 여러 프로젝트에서 디자인 시스템과 공용 컴포넌트 라이브러리를 개발하여 생산성을 높인 경험이 있고 공용 모듈 및 유틸리티 개발은 서비스 전반의 재사용성과 확장성을 높여 유지보수 및 관리의 비용을 줄이는데 도움이 되도록 작업하고 있습니다."),t("p",null,"또한 데이터 시각화의 방식으로 SVG, canvas등 다양한 인터렉션을 적극 활용하고 있으며 최근에는 3D를 이용한 인터렉션에도 크게 관심을 갖고 개발하고 있습니다."),t("p",null,"최근 AI를 이용한 데이터 시각화 작업의 경험과 AI를 활용한 개발 등 AI 관련 기술을 활용하여 그동안의 쌓아온 역량과 결합하는 시도들을 계속해서 하고 있습니다."),t("p",null,"감사합니다.")],-1),n('<h2 id="경력" tabindex="-1">경력 <a class="header-anchor" href="#경력" aria-label="Permalink to &quot;경력&quot;">​</a></h2><h3 id="주-포그리트-frontend-developer" tabindex="-1">(주) 포그리트 <span class="be-gray-text light">| Frontend Developer</span> <a class="header-anchor" href="#주-포그리트-frontend-developer" aria-label="Permalink to &quot;(주) 포그리트 &lt;span class=&quot;be-gray-text light&quot;&gt;| Frontend Developer&lt;/span&gt;&quot;">​</a></h3><p class="range-date">2023.12 – 2025.05 (1Y 6M)</p><h6 id="analytics-데이터-시각화" tabindex="-1">Analytics 데이터 시각화 <a class="header-anchor" href="#analytics-데이터-시각화" aria-label="Permalink to &quot;Analytics 데이터 시각화&quot;">​</a></h6><ul><li><strong>오래된 빌드 환경 개선</strong> 을 통해 모듈, 프레임워크 성능을 향상 시켰습니다. (Vite, Vue3로 업데이트 정책 반영)</li><li>신규 프로젝트의 초기 화면 구조를 설계하고 <strong>디자인시스템 + UI 컴포넌트</strong> 도입으로 개발 및 유지보수 관리 포인트를 줄였습니다. (UI 컴포넌트 라이브러리: <a href="https://beui.vercel.app" target="_blank" rel="noreferrer"><code>BEUI</code></a>)</li><li>SVG를 이용한 <strong>다중 인터렉션을 직접 구현</strong>하여, 요구기능에 대한 UX 및 상호작용의 디테일을 쉽게 제어할 수 있도록 했습니다.</li><li><strong>대량 동적 데이터의 시각화 처리를 개선</strong>하여 리랜더링 성능을 개선했습니다. (스크립트 처리량을 줄이고 데이터 변화에 반응한 리랜더로 전환)</li><li>다국어 폰트 로드 시 발생하던 <strong>FOUT 현상 문제를 해결</strong>하고 리소스 최적화했습니다.</li><li>Nuxt.js 환경에서 <strong>다국어 SEO 문제를 개선</strong>하여 링크 공유 시 표시되는 다국어 컨텐츠 제어할 수 있도록 했습니다.</li><li><strong>AI 데이터 시각화</strong>의 여러 방식을 테스트 하여 HTML 템플릿에 바인딩 가능한 컨텍스트를 만드는 작업에 기여했습니다.</li></ul><hr><h3 id="주-가비아-frontend-developer" tabindex="-1">(주) 가비아 <span class="be-gray-text light">| Frontend Developer</span> <a class="header-anchor" href="#주-가비아-frontend-developer" aria-label="Permalink to &quot;(주) 가비아 &lt;span class=&quot;be-gray-text light&quot;&gt;| Frontend Developer&lt;/span&gt;&quot;">​</a></h3><p class="range-date">2019.11 – 2023.02 (3Y 4M)</p><h6 id="design-system-ui-ux-components" tabindex="-1">Design system &amp; UI/UX Components <a class="header-anchor" href="#design-system-ui-ux-components" aria-label="Permalink to &quot;Design system &amp; UI/UX Components&quot;">​</a></h6><ul><li>디자인 토큰을 이용한 CSS 프레임워크 설계 (<a href="https://frog-ui-css.vercel.app" target="_blank" rel="noreferrer"><code>Frog UI</code></a>)</li><li>scss 프레임워크 + Headless UI 라이브러리 형식을 위해 스타일을 분리하여 다양한 프론트 환경에서 독립적으로 사용 가능하도록 설계했습니다.</li><li>테마별 토큰을 기반으로 서로 다른 테마의 정적 파일(.css)로 빌드해, 여러 서비스별 스타일을 생성할 수 있도록 설계하였습니다.</li></ul><h6 id="frontend-cloud-admin-part" tabindex="-1">Frontend - Cloud Admin part <a class="header-anchor" href="#frontend-cloud-admin-part" aria-label="Permalink to &quot;Frontend - Cloud Admin part&quot;">​</a></h6><ul><li>신규 프로젝트의 초기 화면 설계, 전용 UI 라이브러리 개발였습니다. ( 전용 UI 라이브러리: <a href="https://noistommy.github.io/nt-ui" target="_blank" rel="noreferrer"><code>GAUI</code></a> )</li></ul><h6 id="hiworks-group-platform-team-tf" tabindex="-1">Hiworks Group platform Team (TF) <a class="header-anchor" href="#hiworks-group-platform-team-tf" aria-label="Permalink to &quot;Hiworks Group platform Team (TF)&quot;">​</a></h6><ul><li>Vue 프레임워크 기술 개선의 역할로 참여하여 지연되던 프로젝트를 정상화 하고, 팀의 Vue 기술 정책 수립에 기여했습니다.</li><li>개별 UI 컴포넌트를 통합하여 전용 라이브러리를 구축하고 기존 외부 라이브러리 제거 하여 커스텀, 유지보수 비용을 줄이는 데 기여했습니다.</li><li>전용 UI 라이브러리 가이드 사이트를 작성,공유하여 다른 부서와의 원활한 의사소통을 원활하게 했습니다. ( 가이드 사이트 : <a href="https://noistommy.github.io/hw_ui" target="_blank" rel="noreferrer"><code>HWUI</code></a>)</li><li>기존의 리치 모듈을 대신하여 불필요한 기능을 제거한 경량화 모듈을 개발했습니다. (<a href="https://noistommy.github.io/vue-nt-modal" target="_blank" rel="noreferrer"><code>Modal</code></a>, <a href="https://noistommy.github.io/vue-nt-toast" target="_blank" rel="noreferrer"><code>Toast</code></a>, <a href="https://noistommy.github.io/vue-nt-tooltip" target="_blank" rel="noreferrer"><code>Tooltip</code></a>, Text Editor, DatePicker 등..)</li></ul><h6 id="font-branding-site-dev-tf" tabindex="-1">Font Branding site Dev (TF) <a class="header-anchor" href="#font-branding-site-dev-tf" aria-label="Permalink to &quot;Font Branding site Dev (TF)&quot;">​</a></h6><ul><li>SVG 스크롤 에니메이션 기반 인터렉션 구현</li><li>인터랙션 설계에 참여해 실제 구현 테스트를 반복하며 과도한 스펙의 인터랙션을 적용 가능한 형태로 조율했고, 최종 결과물에 대해 좋은 평가를 받아 이후 팀 내 인터랙션 작업에 참고 사례로 활용되었습니다.</li></ul><hr><h3 id="엔쓰리엔-주-frontend-developer" tabindex="-1">엔쓰리엔(주) <span class="be-gray-text light">| Frontend Developer</span> <a class="header-anchor" href="#엔쓰리엔-주-frontend-developer" aria-label="Permalink to &quot;엔쓰리엔(주) &lt;span class=&quot;be-gray-text light&quot;&gt;| Frontend Developer&lt;/span&gt;&quot;">​</a></h3><p class="range-date">2017.10 – 2019.11 (2Y 1M)</p><h6 id="관제-솔루션-내-통계데이터-시각화" tabindex="-1">관제 솔루션 내 통계데이터 시각화 <a class="header-anchor" href="#관제-솔루션-내-통계데이터-시각화" aria-label="Permalink to &quot;관제 솔루션 내 통계데이터 시각화&quot;">​</a></h6><ul><li>클라이언트별 다양한 데이터를 상황에 맞도록 직접 기획과 UI 설계를 통해 구현했습니다.</li><li>다양한 요구사항에 맞춘 차트 컴포넌트를 직접 개발하여 재사용성을 높이고 유지보수가 쉽도록 개선했습니다.</li></ul><h6 id="재난-대응-관리-sop-솔루션" tabindex="-1">재난 대응 관리 SOP 솔루션 <a class="header-anchor" href="#재난-대응-관리-sop-솔루션" aria-label="Permalink to &quot;재난 대응 관리 SOP 솔루션&quot;">​</a></h6><ul><li>솔루션 내부 기능을 독립된 솔루션으로 확장할 수 있도록 기여했습니다.</li><li>기획, 개발, UI/UX 설계 전 과정 참여하여 직접 클라이언트와 소통하는 과정을 통해 UI/UX 설계 경험을 폭넓게 쌓았습니다.</li></ul><h3 id="snmp-소셜-네트워크-마케팅-플랫폼-frontend-developer" tabindex="-1">SNMP(소셜 네트워크 마케팅 플랫폼) <span class="be-gray-text light">| Frontend Developer</span> <a class="header-anchor" href="#snmp-소셜-네트워크-마케팅-플랫폼-frontend-developer" aria-label="Permalink to &quot;SNMP(소셜 네트워크 마케팅 플랫폼) &lt;span class=&quot;be-gray-text light&quot;&gt;| Frontend Developer&lt;/span&gt;&quot;">​</a></h3><p class="range-date">2014.08 – 2016.10 (2Y 2M)</p><h6 id="모바일-기반-오픈마켓-플랫폼" tabindex="-1">모바일 기반 오픈마켓 플랫폼 <a class="header-anchor" href="#모바일-기반-오픈마켓-플랫폼" aria-label="Permalink to &quot;모바일 기반 오픈마켓 플랫폼&quot;">​</a></h6><ul><li>오픈마켓 웹 및 관리자 플랫폼, 브랜드 페이지 개발</li><li>마케팅 페이지 개발</li></ul><h2 id="오픈-소스" tabindex="-1">오픈 소스 <a class="header-anchor" href="#오픈-소스" aria-label="Permalink to &quot;오픈 소스&quot;">​</a></h2><h6 id="vue-nt-modal-npm-git" tabindex="-1">vue-nt-modal (<a href="https://www.npmjs.com/package/vue-nt-modal" target="_blank" rel="noreferrer"><code>npm</code></a>, <a href="https://github.com/noistommy/vue-nt-modal.git" target="_blank" rel="noreferrer"><code>git</code></a>) <a class="header-anchor" href="#vue-nt-modal-npm-git" aria-label="Permalink to &quot;vue-nt-modal ([`npm`](https://www.npmjs.com/package/vue-nt-modal), [`git`](https://github.com/noistommy/vue-nt-modal.git))&quot;">​</a></h6><ul><li>Demo: <a href="https://noistommy.github.io/vue-nt-modal" target="_blank" rel="noreferrer">https://noistommy.github.io/vue-nt-modal</a></li><li>Teleport를 이용한 Vue.js 전용 Modal 플러그인</li></ul><h6 id="vue-nt-toast-npm-git" tabindex="-1">vue-nt-toast (<a href="https://www.npmjs.com/package/vue-nt-toast" target="_blank" rel="noreferrer"><code>npm</code></a>, <a href="https://github.com/noistommy/vue-nt-toast.git" target="_blank" rel="noreferrer"><code>git</code></a>) <a class="header-anchor" href="#vue-nt-toast-npm-git" aria-label="Permalink to &quot;vue-nt-toast ([`npm`](https://www.npmjs.com/package/vue-nt-toast), [`git`](https://github.com/noistommy/vue-nt-toast.git))&quot;">​</a></h6><ul><li>Demo: <a href="https://noistommy.github.io/vue-nt-toast" target="_blank" rel="noreferrer">https://noistommy.github.io/vue-nt-toast</a></li><li>Vue.js 전용 Toast 플러그인</li><li>다중 알림, 자동 삭제, 스넥바 모드 등 제공</li></ul><h6 id="react-nt-toast-npm-git" tabindex="-1">react-nt-toast (<a href="https://www.npmjs.com/package/react-nt-toast" target="_blank" rel="noreferrer"><code>npm</code></a>, <a href="https://github.com/noistommy/react-nt-toast.git" target="_blank" rel="noreferrer"><code>git</code></a>) <a class="header-anchor" href="#react-nt-toast-npm-git" aria-label="Permalink to &quot;react-nt-toast ([`npm`](https://www.npmjs.com/package/react-nt-toast), [`git`](https://github.com/noistommy/react-nt-toast.git))&quot;">​</a></h6><ul><li>Demo: <a href="https://noistommy.github.io/react-nt-toast" target="_blank" rel="noreferrer">https://noistommy.github.io/react-nt-toast</a></li><li>React 전용 Toast 플러그인</li><li>다중 알림, 자동 삭제, 스넥바 모드 등 제공</li></ul><h6 id="vue-nt-tooltip-npm-git" tabindex="-1">vue-nt-tooltip (<a href="https://www.npmjs.com/package/vue-nt-tooltip" target="_blank" rel="noreferrer"><code>npm</code></a>, <a href="https://github.com/noistommy/vue-nt-tooltip.git" target="_blank" rel="noreferrer"><code>git</code></a>) <a class="header-anchor" href="#vue-nt-tooltip-npm-git" aria-label="Permalink to &quot;vue-nt-tooltip ([`npm`](https://www.npmjs.com/package/vue-nt-tooltip), [`git`](https://github.com/noistommy/vue-nt-tooltip.git))&quot;">​</a></h6><ul><li>Demo: <a href="https://noistommy.github.io/vue-nt-tooltip" target="_blank" rel="noreferrer">https://noistommy.github.io/vue-nt-tooltip</a></li><li>Vue.js 전용 Tooltip 디렉티브</li><li>Top, Bottom, Left, Right 방향 표출</li><li>directive로 구현되어 간단하게 적용 가능</li></ul><h2 id="기술" tabindex="-1">기술 <a class="header-anchor" href="#기술" aria-label="Permalink to &quot;기술&quot;">​</a></h2><p class="large bold">Vue3, Vue2, react, Nuxt.js, Typescript, javascript(ES6+), HTML5, CSS, SCSS(dart), Vite, webpack, gulp, git, SVG, canvas, chart</p><h2 id="학력" tabindex="-1">학력 <a class="header-anchor" href="#학력" aria-label="Permalink to &quot;학력&quot;">​</a></h2><ul><li><strong>국립공주대학교</strong> — 컴퓨터·멀티미디어공학 전공 (2008.02 졸업)</li></ul><h2 id="개인-프로젝트" tabindex="-1">개인 프로젝트 <a class="header-anchor" href="#개인-프로젝트" aria-label="Permalink to &quot;개인 프로젝트&quot;">​</a></h2><p><a href="https://nt-cabinet.notion.site/NT-Play-Room-1f133071ca604d9ebed0394665dc39aa" target="_blank" rel="noreferrer"><code>Nt-Cabinet</code></a></p><ul><li>자체 제작 UI 컴포넌트 라이브러리 (BEUI, BEUI(React), GAUI, HWUI, FROG-UI)</li><li>플러그인 NPM 모듈 3</li><li>기타 프로젝트 (Puzzle game, Roulette)</li></ul>',43)])])}const b=o(i,[["render",s]]);export{g as __pageData,b as default};
